import csv
import io
import re
from collections import Counter
from typing import List, Dict, Union


def parse_csv(raw_csv: str):
    expected_width = 9

    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    try:
        parsed_rows = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    except csv.Error:
        parsed_rows = list(csv.reader(io.StringIO(raw_csv), delimiter=",", quotechar='"', strict=False))

    def is_empty(row: List[str]) -> bool:
        return not row or all(value.strip() == "" for value in row)

    def normalized(row: List[str]):
        return tuple(re.sub(r"\s+", " ", value.strip()).casefold() for value in row)

    def header_score(row: List[str]) -> int:
        score = 0
        for value in row:
            text = value.strip()
            if not text:
                score -= 1
                continue
            if re.fullmatch(r"\d{1,4}[/-]\d{1,2}[/-]\d{1,4}", text):
                score -= 5
            elif re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?", text):
                score -= 5
            elif re.fullmatch(r"[+-]?\d+(?:\.\d+)?", text):
                score -= 4
            elif re.fullmatch(r"[$€£¥]\s*\d+(?:[.,]\d+)?", text):
                score -= 4
            elif re.match(r"(?i)^(?:https?|ftp)://", text):
                score -= 5
            elif re.search(r"[A-Za-z]", text):
                score += 2
                if re.fullmatch(r"[A-Za-z][A-Za-z0-9 _./()#&%-]*", text):
                    score += 1
        return score

    full_width_rows = [row for row in parsed_rows if len(row) == expected_width and not is_empty(row)]
    counts = Counter(normalized(row) for row in full_width_rows)

    repeated_candidates = [
        row for row in full_width_rows
        if counts[normalized(row)] >= 2
    ]

    if repeated_candidates:
        header = max(
            repeated_candidates,
            key=lambda row: (header_score(row), counts[normalized(row)])
        )
    elif full_width_rows:
        header = max(full_width_rows, key=header_score)
    else:
        header = ["column_" + str(index + 1) for index in range(expected_width)]

    header_key = normalized(header)

    start_index = 0
    for index, row in enumerate(parsed_rows):
        if is_empty(row):
            continue
        if len(row) >= expected_width - 1 or normalized(row) == header_key:
            start_index = index
            break
    else:
        return {"columns": list(header), "rows": []}

    def repair_width(row: List[str]) -> List[str]:
        if len(row) == expected_width:
            return list(row)
        if len(row) < expected_width:
            return list(row) + [""] * (expected_width - len(row))

        url_index = None
        for index, value in enumerate(row):
            if re.match(r"(?i)^\s*(?:https?|ftp)://", value):
                url_index = index
                break

        if url_index is not None and url_index >= 7:
            prefix = list(row[:5])
            middle = row[5:url_index]
            if len(middle) >= 2:
                product = ",".join(middle[:-1])
                description = middle[-1]
            elif len(middle) == 1:
                product = middle[0]
                description = ""
            else:
                product = ""
                description = ""
            comments = ",".join(row[url_index + 1:])
            repaired = prefix + [product, description, row[url_index], comments]
            if len(repaired) == expected_width:
                return repaired

        return list(row[:expected_width - 1]) + [",".join(row[expected_width - 1:])]

    output_rows = []
    for row in parsed_rows[start_index:]:
        if is_empty(row):
            continue
        if normalized(row) == header_key:
            continue
        output_rows.append(repair_width(row))

    return {"columns": list(header), "rows": output_rows}
